// One live opencode run via OpenRouter that posts a board comment_task through the per-run
// OPENCODE_CONFIG board MCP. Records raw stdout JSONL as the parser fixture. Run ONCE.
const path = require('path');
const fs = require('fs');
const os = require('os');
const APP = '/Users/d/hice/agents-squad/.squad/worktrees/t_eddfd6eb/app';
const { Store } = require(path.join(APP, 'src/store'));
const RT = require(path.join(APP, 'src/runtimes'));
const { spawn } = require('child_process');

const scratch = fs.mkdtempSync(path.join(os.tmpdir(), 'oc-live-smoke-'));
const store = new Store(scratch);
const settings = { ...store.getSettings(), permissionMode: 'bypassPermissions' };
const key = JSON.parse(fs.readFileSync(path.join(os.homedir(), '.pi/agent/auth.json'), 'utf8')).openrouter.key;
const node = store.addNode({
  id: 'n_ocsmoke', name: 'OcSmoke', role: 'QA', runtime: 'opencode',
  model: 'openrouter/~google/gemini-flash-latest', effort: 'low',
  disabledBoardTools: ['list_team', 'list_tasks', 'create_task', 'reassign_task', 'update_task_status', 'send_message', 'read_messages', 'ask_human', 'read_wiki', 'write_wiki', 'recruit_agent', 'retire_agent', 'update_agent'],
  env: { OPENROUTER_API_KEY: key },
});
const task = store.createTask({ title: 'OpenCode live smoke', description: 'One board comment via the opencode runtime.', assignee: node.id });
const mcp = { mcpServers: { board: { type: 'stdio', command: process.execPath, args: [path.join(APP, 'src/mcp-server.js'), '--project', store.dir, '--node', node.id], env: { ELECTRON_RUN_AS_NODE: '1' } } } };
const env = { ...process.env, OPENROUTER_API_KEY: key };
const prompt = `Use the board tool comment_task once to comment on task ${task.id} (author OcSmoke, text "OpenCode live smoke via OpenRouter: board comment_task reached the board."). Then reply exactly: DONE.`;

(async () => {
  const rt = RT.getRuntime('opencode');
  const args = await rt.buildArgs(node, prompt, settings, mcp, { env });
  console.error('ARGV:', JSON.stringify(args.map((a) => (a === prompt ? '<prompt>' : a))));
  console.error('OPENCODE_CONFIG:', env.OPENCODE_CONFIG);
  console.error('config file:', fs.readFileSync(env.OPENCODE_CONFIG, 'utf8'));
  const out = [];
  const child = spawn(rt.bin(settings), args, { cwd: scratch, env, stdio: ['ignore', 'pipe', 'pipe'] });
  let stderr = '';
  child.stdout.on('data', (d) => {
    for (const line of d.toString().split('\n')) {
      const t = line.trim(); if (!t) continue;
      out.push(t);
      try { const o = rt.parseEvent(JSON.parse(t), settings); for (const [k, v] of o.logs) console.error('  [' + k + ']', String(v).slice(0, 160)); if (o.tokens) console.error('  tokens', JSON.stringify(o.tokens), 'cost', o.cost, 'done', o.done); } catch (e) { console.error('  parse-fail', e.message); }
    }
  });
  child.stderr.on('data', (d) => { stderr += d.toString(); });
  const code = await new Promise((res) => child.on('close', res));
  fs.writeFileSync(path.join(APP, 'test/fixtures/probe-opencode-live.jsonl'), out.join('\n') + '\n');
  console.error('EXIT', code, '| events', out.length, '| stderr', JSON.stringify(stderr.slice(0, 300)));
  const after = store.getTask(task.id);
  console.error('TASK COMMENTS:', JSON.stringify((after.comments || []).map((c) => ({ author: c.author, text: c.text.slice(0, 120) }))));
  console.error('SCRATCH DIR:', scratch);
})().catch((e) => { console.error('LIVE FAIL', e); process.exit(1); });

